('advanced-native-928', '["phrase"]'::jsonb, '{"advanced-native-928-v1-audio":{"type":"mc","answers":["People began talking more comfortably before the project discussion."],"options":["People began talking more comfortably before the project discussion.","The group settled the project plan before discussing their journeys.","People became quieter because the question ended the conversation.","The question required everyone to explain a private difficulty."]},"advanced-native-928-v2-reply":{"type":"mc","answers":["We needed a relaxed first exchange before focusing on the work.","It gave us an easy shared topic before the project discussion.","I hoped it would break the ice so people felt more comfortable speaking.","A simple opening could help people begin talking without sharing anything private."],"options":["We needed a relaxed first exchange before focusing on the work.","It gave us an easy shared topic before the project discussion.","I hoped it would break the ice so people felt more comfortable speaking.","A simple opening could help people begin talking without sharing anything private."]},"advanced-native-928-v1-scene":{"type":"mc","answers":["The question helped break the ice before the activity."],"options":["The question completed the group’s decisions about the final design.","The exchange kept members from speaking to one another.","The question helped break the ice before the activity."]},"advanced-native-928-v1-contrast":{"type":"mc","answers":["An opener leaves people more reluctant to speak and ends the exchange."],"options":["A simple introduction makes the first exchange easier.","A light shared question helps people start chatting.","An opener leaves people more reluctant to speak and ends the exchange."]},"advanced-native-928-v1-branch":{"type":"mc","answers":["Let us break the ice with an easy shared topic that people can choose to answer."],"options":["We could begin by asking which new member seems the most nervous.","Let us break the ice wi